/// The advance of `c` in em, if the face carries it.
pub(super) fn advance_em(c: char) -> Option<f64> {
    let u = c as u32;
    let mut off = 0usize;
    for &(lo, hi) in COVERED {
        if u < lo { return None; }
        if u <= hi { return Some(ADV[off + (u - lo) as usize] as f64 / 1000.0); }
        off += (hi - lo + 1) as usize;
    }
    None
}

/// Whether the face carries `c` (a C0 control counts as carried: the parser never passes one through).
pub(super) fn covered(c: char) -> bool {
    let u = c as u32;
    COVERED.iter().any(|&(lo, hi)| lo <= u && u <= hi)
}
